class Solution {
public:
    void solve(int i,int j,vector<int> nums,vector<vector<int>> &ans)
    {
        if(i==j-1)
        {
            ans.push_back(nums);
            return;
        }
        for(int k=i;k<j;k++)
        {
            if(i!=k and nums[i]==nums[k])
                continue;
            swap(nums[i],nums[k]);
            solve(i+1,j,nums,ans);
        }
    }
    vector<vector<int>> permuteUnique(vector<int>& nums) {
        sort(nums.begin(),nums.end());
        vector<vector<int>> ans;
        solve(0,nums.size(),nums,ans);
        return ans;
    }
};

from collections import Counter
class Solution(object):
    def permuteUnique(self, nums):
        """
        :type nums: List[int]
        :rtype: List[List[int]]
        """
        if not nums: return []
        self.counter = Counter(nums)
        self.result = []
        self.recurse(self.counter, [])
        return self.result

    def recurse(self, counter, partial, last=None):
        if len(counter.keys())==1:
            final = counter.keys()[0]
            self.result.append(partial +[final]*counter[final])
        else:
            for key in counter.keys():
                if last is not None and key==last: continue
                for i in range(1, counter[key]+1):
                    _counter = counter.copy()
                    _counter[key]-=i
                    if _counter[key]==0: 
                        del _counter[key]
                    self.recurse(_counter, partial+[key]*i, key)

